   159→/// <remark>
   160→///  Ensure that non Blob transactions do not contain Blob specific fields.
   161→///  This validator will be deprecated once we have a proper Transaction type hierarchy.
   162→/// </remark>
   163→public sealed class NonBlobFieldsTxValidator : ITxValidator
   164→{
   165→    public static readonly NonBlobFieldsTxValidator Instance = new();
   166→    private NonBlobFieldsTxValidator() { }
   167→
   168→    public ValidationResult IsWellFormed(Transaction transaction, IReleaseSpec releaseSpec) => transaction switch
   169→    {
   170→        // Execution-payload version verification
   171→        { MaxFeePerBlobGas: not null } => TxErrorMessages.NotAllowedMaxFeePerBlobGas,
   172→        { BlobVersionedHashes: not null } => TxErrorMessages.NotAllowedBlobVersionedHashes,
   173→        { NetworkWrapper: ShardBlobNetworkWrapper } => TxErrorMessages.InvalidTransactionForm,
   174→        _ => ValidationResult.Success
   175→    };
   176→}
   177→
   178→public sealed class NonSetCodeFieldsTxValidator : ITxValidator
   179→{
   180→    public static readonly NonSetCodeFieldsTxValidator Instance = new();
   181→    private NonSetCodeFieldsTxValidator() { }
   182→
   183→    public ValidationResult IsWellFormed(Transaction transaction, IReleaseSpec releaseSpec) => transaction switch
   184→    {
   185→        { AuthorizationList: not null } => TxErrorMessages.NotAllowedAuthorizationList,
   186→        _ => ValidationResult.Success
   187→    };
   188→}
   189→
   190→public sealed class BlobFieldsTxValidator : ITxValidator
   191→{
   192→    public static readonly BlobFieldsTxValidator Instance = new();
   193→    private BlobFieldsTxValidator() { }
   194→
   195→    public ValidationResult IsWellFormed(Transaction transaction, IReleaseSpec releaseSpec) =>
   196→        transaction switch
   197→        {
   198→            { To: null } => TxErrorMessages.TxMissingTo,
   199→            { MaxFeePerBlobGas: null } => TxErrorMessages.BlobTxMissingMaxFeePerBlobGas,
   200→            { BlobVersionedHashes: null } => TxErrorMessages.BlobTxMissingBlobVersionedHashes,
   201→            _ => ValidateBlobFields(transaction, releaseSpec)
   202→        };
   203→
   204→    private static ValidationResult ValidateBlobFields(Transaction transaction, IReleaseSpec spec)
   205→    {
   206→        int blobCount = transaction.BlobVersionedHashes!.Length;
   207→
   208→        ValidationResult blobPerTxLimitValidationResult = ValidateBlobGasLimits(blobCount, spec);
   209→
   210→        if (!blobPerTxLimitValidationResult)
   211→        {
   212→            return blobPerTxLimitValidationResult;
   213→        }
   214→
   215→        for (int i = 0; i < blobCount; i++)
   216→        {
   217→            switch (transaction.BlobVersionedHashes[i])
   218→            {
   219→                case null: return TxErrorMessages.MissingBlobVersionedHash;
   220→                case { Length: not KzgPolynomialCommitments.BytesPerBlobVersionedHash }: return TxErrorMessages.InvalidBlobVersionedHashSize;
   221→                case { Length: KzgPolynomialCommitments.BytesPerBlobVersionedHash } when transaction.BlobVersionedHashes[i][0] != KzgPolynomialCommitments.KzgBlobHashVersionV1: return TxErrorMessages.InvalidBlobVersionedHashVersion;
   222→            }
   223→        }
   224→
   225→        return ValidationResult.Success;
   226→    }
   227→
   228→    internal static ValidationResult ValidateBlobGasLimits(int txBlobCount, IReleaseSpec spec)
   229→    {
   230→        if (txBlobCount < Eip4844Constants.MinBlobsPerTransaction)
   231→        {
   232→            return TxErrorMessages.BlobTxMissingBlobs;
   233→        }
   234→
   235→        ulong txBlobGas = BlobGasCalculator.CalculateBlobGas(txBlobCount);
   236→
   237→        ulong maxBlobGasPerBlock = spec.GetMaxBlobGasPerBlock();
   238→
   239→        if (txBlobGas > maxBlobGasPerBlock)
   240→        {
   241→            return BlockErrorMessages.BlobGasUsedAboveBlockLimit(maxBlobGasPerBlock, txBlobCount, txBlobGas);
   242→        }
   243→
   244→        ulong maxBlobGasPerTx = spec.GetMaxBlobGasPerTx();
   245→
   246→        return txBlobGas > maxBlobGasPerTx ? TxErrorMessages.BlobTxGasLimitExceeded(txBlobGas, maxBlobGasPerTx) : ValidationResult.Success;
   247→    }
   248→}
   249→
   250→public sealed class MaxBlobCountBlobTxValidator : ITxValidator
   251→{
   252→    public static readonly MaxBlobCountBlobTxValidator Instance = new();
   253→    private MaxBlobCountBlobTxValidator() { }
   254→
   255→    public ValidationResult IsWellFormed(Transaction transaction, IReleaseSpec releaseSpec) =>
   256→        transaction switch
   257→        {
   258→            { Type: not TxType.Blob } => ValidationResult.Success,
   259→            _ => ValidateBlobFields(transaction, releaseSpec)
   260→        };
   261→
   262→    private static ValidationResult ValidateBlobFields(Transaction transaction, IReleaseSpec spec) =>
   263→        BlobFieldsTxValidator.ValidateBlobGasLimits(transaction.BlobVersionedHashes?.Length ?? 0, spec);
   264→}
